INSERT INTO magnet_v2_parse_job (
    parse_uuid, user_id, input_type, input_hash, btih, btmh, trackers_json,
    input_storage_key, resource_id, status, revision, retry_count, next_retry_at,
    error_code, error_message, created_at, updated_at
) VALUES (
    #{parseUuid}, #{userId}, #{inputType}, #{inputHash}, #{btih}, #{btmh}, #{trackersJson},
    #{inputStorageKey}, #{resourceId}, #{status}, #{revision}, #{retryCount}, #{nextRetryAt},
    #{errorCode}, #{errorMessage}, #{createdAt}, #{updatedAt}
)

