UPDATE magnet_v2_parse_job
SET status = 'FAILED',
    revision = revision + 1,
    error_code = #{errorCode},
    error_message = #{errorMessage},
    updated_at = CURRENT_TIMESTAMP(6)
WHERE id = #{id}
  AND user_id = #{userId}
  AND revision = #{expectedRevision}
  AND deleted = 0

UPDATE magnet_v2_parse_job
SET deleted = id, updated_at = CURRENT_TIMESTAMP(6)
WHERE id = #{id}
  AND user_id = #{userId}
  AND deleted = 0
